#![cfg(unix)]
use baal_transport_service::{Authority,Permit,Config,Transport,DisabledCredentials,Clock,multi_leg,multi_leg_portfolio as wire,admission::AccountAdmission};
use moloch_live_runtime::{authority::SharedAuthority,package_authority::Prepared,probabilistic_portfolio as prob};
use serde_json::{json,Value};
use std::collections::BTreeSet;
#[path="support/probabilistic_fixture.rs"]mod support;
use support::*;
#[test]fn opaque_qualified_model_to_real_native_attempt_to_physical_authority_preserves_financial_state(){let a=A::new(true);let before=a.f.bank.engine().report().unwrap();let p=a.ready().unwrap();assert!(p.requires_entry());p.authorize(&a.spec,&a.permit,a.at,&BTreeSet::new(),a.activation.entry_until_ms).unwrap();assert!(a.plan.validate_current(&a.f.bank,&a.log,&a.f.scope,&policy(&a.f),a.at).is_err(),"pre-reserve boundary is deliberately obsolete, not silently reused");let auth=a.authority();auth.prepare_probabilistic(&a.f.bank,&a.plan,&a.reservation,&a.basket,a.permit.clone(),a.facts.clone(),&a.log,a.at).unwrap();auth.authorize(&a.f.scope,&a.spec,&a.permit,true,a.at).unwrap();assert_eq!(a.f.bank.engine().report().unwrap(),before);assert!(a.f.bank.engine().fills().is_empty());assert_eq!(a.f.bank.engine().package_records()[0]["probabilistic"]["guaranteedArbitrage"],false);}
#[test]fn no_physical_authority_before_native_attempt_or_after_unknown_acceptance(){let a=A::new(false);assert!(a.ready().is_err());let mut a=A::new(true);let e=json!({"type":"probabilistic_portfolio_unknown_v1","source":"moloch_live_dispatcher","receivedAt":iso(a.at+1),"packageId":a.reservation.event()["packageId"],"proofHash":a.reservation.event()["proofHash"],"bankScope":a.reservation.event()["bankScope"],"requestHash":hash(&a.spec)});a.f.bank.accept("prob-authority",3,&e).unwrap();assert!(a.ready().is_err());}
#[test]fn rehashed_mutated_risk_json_accepted_by_native_is_not_the_original_opaque_reservation(){let a=A::with_mutated_reserve(|r|{r["qualification"]["risk"]["maximumIncrementalCvarLoss"]=json!("99.000000");let sha=hash(&r["qualification"]);r["proofHash"]=json!(sha);r["packageId"]=json!(format!("prob-{}",r["proofHash"].as_str().unwrap()));});assert_eq!(a.f.bank.engine().package_records()[0]["phase"],"attempted");assert_ne!(a.f.bank.engine().package_records()[0]["proofHash"],a.reservation.event()["proofHash"]);assert!(a.ready().is_err());}
#[test]fn actual_current_wallet_basis_and_zero_ack_fill_boundary_are_required(){let mut a=A::new(true);let q=a.f.bank.engine().order_records().into_iter().find(|q|a.f.bank.engine().is_package_order(q["id"].as_u64().unwrap())).unwrap();let at=iso(a.at);let mut ack=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderId":q["id"],"actualOrderId":"99001","exchangeId":q["exchangeId"],"marketId":q["marketId"],"side":q["side"],"action":q["action"],"quantity":q["quantity"],"price":q["price"],"receivedAt":at});a.f.bank.accept("prob-authority",3,&ack).unwrap();assert!(a.ready().is_err(),"zero fills does not authorize a second write after any ACK");ack["type"]=json!("actual_fill");ack["fillId"]=json!("88001");ack["fee"]=json!("0.000000");ack["executedAt"]=ack["receivedAt"].clone();a.f.bank.accept("prob-authority",4,&ack).unwrap();assert!(a.ready().is_err(),"original positions SHA cannot survive an actual fill");}
#[test]fn all_official_positions_including_unmodeled_inventory_must_match_exact_native_quantities(){for case in ["missing","quantity","foreign","duplicate"]{let mut a=A::with_unmodeled_held(true);assert!(a.ready().is_ok());assert!(a.basket.legs.iter().all(|l|l.exchange_id!="106"));let rows=a.facts.positions.data["positions"].as_array_mut().unwrap();match case{"missing"=>rows.clear(),"quantity"=>rows[0]["quantity"]=json!(4),"foreign"=>rows.push(json!({"exchangeId":"999","marketId":"999","quantity":1})),_=>rows.push(rows[0].clone())};assert!(a.ready().is_err(),"{case}");}}
#[test]fn each_original_ordered_action_side_limit_and_permit_is_frozen(){for case in ["action","side","price","quantity","funding","permit"]{let mut a=A::new(true);match case{"action"=>a.basket.legs[0].action=wire::Action::Sell,"side"=>a.basket.legs[0].side=multi_leg::Side::No,"price"=>a.basket.legs[0].limit_price="0.365000".into(),"quantity"=>a.basket.legs[0].quantity+=1,"funding"=>a.basket.maximum_gross_buy_cost="0.000000".into(),_=>a.permit.maximum_quantity=101};assert!(a.ready().is_err(),"{case}");}}
#[test]fn fresh_source_contract_depth_cash_and_complete_account_facts_remain_mandatory(){for case in ["root","depth","cash","positioncoverage","ordercoverage","stale","future"]{let mut a=A::new(true);let ex=a.basket.legs[0].exchange_id.clone();match case{"root"=>a.facts.components.get_mut(&ex).unwrap().contract.data["root"]["contract_details"]["winnerName"]=json!("Other Party"),"depth"=>a.facts.components.get_mut(&ex).unwrap().book.data["contexts"][0]["orderbook"]["exchanges"][0]["asks"][0]["quantity"]=json!(4),"cash"=>a.facts.cash_balance.data=json!({"balance":1,"availableAdvance":99,"buyingPower":100}),"positioncoverage"=>a.facts.positions.data["pagination"]=json!({"hasMore":true}),"ordercoverage"=>a.facts.open_orders.data["coverage"]["complete"]=json!(false),"stale"=>a.facts.components.get_mut(&ex).unwrap().book.request_started_at=iso(a.at-10001),_=>a.facts.cash_balance.received_at=iso(a.at+1)};assert!(a.ready().is_err(),"{case}");}}
#[test]fn nonwire_components_still_need_current_matching_rules_and_full_book(){let mut a=A::new(true);assert!(a.basket.legs.iter().all(|l|l.exchange_id!="101"));a.facts.components.get_mut("101").unwrap().contract.data["root"]["contract_id"]=json!("999");assert!(a.ready().is_err());}
#[test]fn original_dispatch_mutation_unknown_and_managed_cohort_overlap_cannot_populate_authority(){let mut a=A::new(true);let auth=a.authority();auth.require_fundamental_exchanges(&["101".to_string()].into()).unwrap();assert!(auth.prepare_probabilistic(&a.f.bank,&a.plan,&a.reservation,&a.basket,a.permit.clone(),a.facts.clone(),&a.log,a.at).is_err());drop(auth);let auth=a.authority();a.log.append(json!({"kind":"intent","qid":9000})).unwrap();a.log.append(json!({"kind":"attempt","qid":9000})).unwrap();assert!(auth.prepare_probabilistic(&a.f.bank,&a.plan,&a.reservation,&a.basket,a.permit.clone(),a.facts.clone(),&a.log,a.at).is_err());assert!(auth.authorize(&a.f.scope,&a.spec,&a.permit,true,a.at).is_err());}
#[test]fn existing_control_stop_binary_stream_and_exact_request_checks_still_apply(){for case in ["stop","control","binary","stream","body","bytes","expired"]{let a=A::new(true);let auth=a.authority();auth.prepare_probabilistic(&a.f.bank,&a.plan,&a.reservation,&a.basket,a.permit.clone(),a.facts.clone(),&a.log,a.at).unwrap();let mut spec=a.spec.clone();let mut at=a.at;match case{"stop"=>std::fs::write(a.f.root.join("STOP"),b"stop").unwrap(),"control"=>std::fs::write(a.f.root.join("prob-auth-control"),b"changed").unwrap(),"binary"=>std::fs::write(a.f.root.join("prob-auth-binary"),b"changed").unwrap(),"stream"=>auth.bind_stream(std::sync::Arc::new(std::sync::atomic::AtomicBool::new(true)),a.at+1000),"body"=>spec.body.as_mut().unwrap()["legs"][0]["quantity"]=json!(99),"bytes"=>spec.body_json=Some("{}".into()),_=>at=a.plan.expires_at_ms()};assert!(auth.authorize(&a.f.scope,&spec,&a.permit,true,at).is_err(),"{case}");}}
struct FixedClock(u64);impl Clock for FixedClock{fn now_ms(&self)->u64{self.0}fn sleep_ms(&mut self,ms:u64)->baal_transport_service::Result<()>{self.0+=ms;Ok(())}}
#[test]fn real_offline_sdk_queue_blocks_an_unrelated_unknown_without_network_or_bank_mutation(){let a=A::new(true);let auth=a.authority();auth.prepare_probabilistic(&a.f.bank,&a.plan,&a.reservation,&a.basket,a.permit.clone(),a.facts.clone(),&a.log,a.at).unwrap();auth.authorize(&a.f.scope,&a.spec,&a.permit,true,a.at).unwrap();let queue=a.f.root.join("sdk-queue");{let mut q=AccountAdmission::open(&queue,"fixture-account","prior-owner").unwrap();assert_eq!(q.command(json!({"op":"admit","scope":"fixture-account","now":a.at-1,"request":"unrelated","write":true,"binding":{"intent":"unrelated","key":"unrelated-key","payload_hash":"a".repeat(64)},"authorized":true,"lease_valid":true,"permit_valid":true})).unwrap()["admitted"],true);}let mut t=Transport::new_for_mock(Config{queue_dir:queue,account_scope:"fixture-account".into(),scope:a.f.scope.clone(),maximum_pages:20,writes_enabled:true},Box::new(DisabledCredentials),Box::new(FixedClock(a.at)),Box::new(SharedAuthority(auth)),"http://127.0.0.1:1/api/v1".into()).unwrap();let before=a.f.bank.engine().report().unwrap();let err=t.place_portfolio_all_or_none(a.basket.clone(),a.permit.clone()).unwrap_err();assert_eq!(err.code,"PACKAGE_QUEUE_NOT_QUIET");assert!(!err.may_have_executed);assert_eq!(a.f.bank.engine().report().unwrap(),before);}
#[test]fn research_plan_cannot_create_the_opaque_authority_reservation(){let f=F::with_tournament(T);let log=moloch_live_runtime::dispatch::DispatchLog::open(&f.root.join("ordinary.ndjson")).unwrap();let surface=f.bound(NOW).unwrap();let semantic=semantics(&f,&surface);let policy=policy(&f);let plan=prob::optimize(&f.bank,&log,&f.scope,&surface,&semantic,&policy,NOW).unwrap().unwrap();assert!(plan.qualified_reservation(&f.bank,&log,&f.scope,&surface,&semantic,&policy,NOW).is_err());}
